INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$58add61d-ba33-438e-bef4-cbbe75717088$s$, $s$united-states-new-york$s$, 1, $s$United States$s$, $s$US$s$, $s$New York$s$, $s$📍Body Painting, Union Square, Manhattan$s$, $s$Final Canvas: Reliving the Body Painting Magic in Union Square! 🎨✨🗽$s$, $s$📍 Body Painting, Union Square$s$, $s$Remember that unforgettable experience of becoming a living work of art? This post takes you back to our last incredible body painting adventure right in the heart of NYC's Union Square! We're looking back at the vibrant colors, the incredible artists, and the amazing energy of turning public space into a canvas.  🖌️🌟$s$, $s$✨A Farewell to Fantastic: Witnessing the Last NYC Body Painting Day🎨$s$, $s$aroundtheworld50s/blog/united-states-new-york/1/IMG_0731$s$, $s$💥 Insider Tips: Your Key to an Unforgettable Trip (read more...)$s$, $s$united-states-new-york$s$, $s$published$s$, '2025-08-10T00:00:00.000Z'::timestamptz, '2025-08-10T00:00:00.000Z'::timestamptz);
INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$58add61d-ba33-438e-bef4-cbbe75717088$s$, 0, $s$text$s$, $s${"html":"After over a decade of transforming Union Square into a vibrant canvas of human artistry, New York City's annual Body Painting Day ended on July 23, 2023. This final edition was a dazzling spectacle, a vibrant tapestry of colors and creativity as artists meticulously transformed nude models into living masterpieces."}$s$::jsonb),
  ($s$58add61d-ba33-438e-bef4-cbbe75717088$s$, 1, $s$text$s$, $s${"html":"Everywhere we looked, we saw bodies transforming – it was truly mind-blowing to see intricate patterns, wild and fantastical creatures, and vibrant abstract designs come to life right before our eyes. It was a powerful celebration of the human form, showcasing the incredible talent and dedication of every single artist involved.\n\nEach person became their unique masterpiece, a fleeting piece of art that everyone could witness. As the day progressed, the energy in Union Square continued to build, a truly vibrant testament to the power of art and the resilience of the human spirit."}$s$::jsonb),
  ($s$58add61d-ba33-438e-bef4-cbbe75717088$s$, 2, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-new-york/1/IMG_0482","aroundtheworld50s/blog/united-states-new-york/1/IMG_0485","aroundtheworld50s/blog/united-states-new-york/1/IMG_0487","aroundtheworld50s/blog/united-states-new-york/1/IMG_0492","aroundtheworld50s/blog/united-states-new-york/1/IMG_0494","aroundtheworld50s/blog/united-states-new-york/1/IMG_0542","aroundtheworld50s/blog/united-states-new-york/1/IMG_0518","aroundtheworld50s/blog/united-states-new-york/1/IMG_0521","aroundtheworld50s/blog/united-states-new-york/1/IMG_0487","aroundtheworld50s/blog/united-states-new-york/1/IMG_0544","aroundtheworld50s/blog/united-states-new-york/1/IMG_0554","aroundtheworld50s/blog/united-states-new-york/1/IMG_0527"]}$s$::jsonb);
